SELECT analytics_order_facts.payment_method, SUM(analytics_order_facts.net_revenue) AS net_revenue FROM analytics_order_facts WHERE analytics_order_facts.year = 2026 AND analytics_order_facts.month = 5 AND analytics_order_facts.region = 'Central' AND analytics_order_facts.channel = 'retail' AND analytics_order_facts.customer_segment = 'mid_market' AND analytics_order_facts.category = 'category_01' GROUP BY analytics_order_facts.payment_method ORDER BY net_revenue DESC, analytics_order_facts.payment_method ASC LIMIT 12
